function isWeatherText(
  text: string
) {
  return containsAny(
    text,
    [
      "天気",
      "雨",
      "霧雨",
      "雷",
      "降",
      "晴",
      "曇",
      "気温",
      "暑",
      "寒",
      "蒸し",
      "湿気",
      "湿度",
      "風",
    ]
  );
}

function hasRecentMisakiWeatherContext(
  history: ChatMessage[]
) {
  return history
    .slice(-8)
    .some(
      (item) =>
        item.role === "misaki" &&
        isWeatherText(
          item.text
        )
    );
}

function userAskedMisakiWeather(
  message: string
) {
  return (
    isWeatherText(message) &&
    containsAny(
      message,
      [
        "そっち",
        "そちら",
        "美咲",
      ]
    )
  );
}

function userIsActuallyInDanger(
  message: string
) {
  return containsAny(
    message,
    [
      "事故った",
      "事故にあった",
      "怪我した",
      "けがした",
      "血が出て",
      "救急車",
      "病院",
      "倒れた",
      "具合悪い",
      "体調悪い",
      "高熱",
      "息苦しい",
      "地震すごい",
      "避難",
      "冠水",
      "浸水",
      "動けない",
      "閉じ込め",
    ]
  );
}

function findDayTypeProblems(
  reply: string,
  dayType: MisakiDayType,
  currentTime?: string
) {
  const problems: string[] = [];

  if (
    dayType === "work" &&
    containsAny(
      reply,
      [
        "今日は暇",
        "今日は何も予定ない",
        "今日は予定ない",
        "今日は一日のんびり",
        "今日はずっとのんびり",
        "今日はずっとだらだら",
        "一日中だらだら",
      ]
    )
  ) {
    problems.push(
      "今日は仕事の日なのに、一日が完全な休み・暇であるように話している"
    );
  }

  if (
    dayType === "off" &&
    containsAny(
      reply,
      [
        "今日は仕事",
        "今仕事中",
        "勤務中",
        "仕事してる",
        "これから仕事",
        "仕事行ってくる",
      ]
    )
  ) {
    problems.push(
      "今日は休みの日なのに、仕事の日であるように話している"
    );
  }

  if (
    dayType === "work" &&
    currentTime &&
    getHour(currentTime) < 10 &&
    containsAny(
      reply,
      [
        "仕事終わる",
        "仕事が終わる",
        "仕事終わった",
        "勤務が終わる",
        "勤務終わる",
        "あと少しで仕事",
        "もうすぐ仕事終",
      ]
    )
  ) {
    problems.push(
      "朝なのに、美咲が夜勤明けのように仕事の終わりを話している"
    );
  }

  return problems;
}

function getReplyProblems(
  reply: string,
  message: string,
  currentTime: string,
  history: ChatMessage[],
  evidence: ActivityEvidence,
  dayType: MisakiDayType
) {
  const problems = [
    ...findDayTypeProblems(
      reply,
      dayType,
      currentTime
    ),
  ];

  const unsupported =
    findUnsupportedActivityGroups(
      reply,
      evidence
    );

  if (unsupported.length > 0) {
    problems.push(
      `美咲自身の過去行動「${unsupported.join("・")}」を根拠なく作っている`
    );
  }

  const inventedSources = [
    "ニュースで見",
    "テレビで見",
    "SNSで見",
    "スマホで見",
    "ネットで見",
    "通知が来",
    "友達から聞",
    "天気予報だと",
    "予報で言って",
    "予報を見た",
  ];

  if (
    containsAny(
      reply,
      inventedSources
    )
  ) {
    problems.push(
      "リアルタイム情報について架空の情報入手経路を作っている"
    );
  }

  const unsupportedWeatherHistory = [
    "さっきから",
    "朝からずっと",
    "昼からずっと",
    "ずっと雨",
    "ずっと降って",
    "降ったり止んだり",
    "また降ってきた",
    "また降り出した",
  ];

  if (
    isWeatherText(reply) &&
    containsAny(
      reply,
      unsupportedWeatherHistory
    )
  ) {
    problems.push(
      "確認できない天気の時間経過を作っている"
    );
  }

  if (
    isWeatherText(reply) &&
    !hasRecentMisakiWeatherContext(
      history
    ) &&
    containsAny(
      reply,
      [
        "さっきと変わらず",
        "さっきと同じ",
        "さっきより",
      ]
    )
  ) {
    problems.push(
      "直前の美咲の天気発言がないのに過去と比較している"
    );
  }

  if (
    userAskedMisakiWeather(
      message
    )
  ) {
    if (
      containsAny(
        reply,
        [
          "そっちはどう",
          "そちらはどう",
          "そっちは今どんな感じ",
          "そっちの天気は",
        ]
      )
    ) {
      problems.push(
        "美咲側の天気を聞かれているのに質問し返している"
      );
    }

    if (
      containsAny(
        reply,
        [
          "傘持ったほう",
          "傘を持ったほう",
          "傘忘れないで",
          "濡れないようにして",
        ]
      )
    ) {
      problems.push(
        "美咲側の天気を聞かれただけなのに行動アドバイスを追加している"
      );
    }
  }

  if (
    !userIsActuallyInDanger(
      message
    ) &&
    containsAny(
      reply,
      [
        "そっちは大丈夫",
        "大丈夫？",
        "影響ない？",
        "平気？",
        "無事？",
        "気をつけてね",
        "無理しないでね",
        "安全第一で",
      ]
    )
  ) {
    problems.push(
      "通常雑談なのに過剰な心配を付けている"
    );
  }

  if (
    getHour(currentTime) < 5 &&
    containsAny(
      reply,
      [
        "今朝",
        "朝から",
        "朝起きて",
        "起きたら",
      ]
    )
  ) {
    problems.push(
      "深夜なのに朝として話している"
    );
  }

  return problems;
}

function removeProblemSentences(
  reply: string,
  problemsForSentence: (
    sentence: string
  ) => string[]
) {
  const parts =
    reply.match(
      /[^。！？!?]+[。！？!?]?/gu
    ) ?? [reply];

  return parts
    .filter(
      (part) =>
        problemsForSentence(
          part
        ).length === 0
    )
    .join("")
    .trim();
}

function cleanFinalReply(
  reply: string,
  message: string,
  evidence: ActivityEvidence,
  dayType: MisakiDayType
) {
  let cleaned =
    removeProblemSentences(
      reply,
      (sentence) => [
        ...findDayTypeProblems(
          sentence,
          dayType
        ),
        ...(
          findUnsupportedActivityGroups(
            sentence,
            evidence
          ).length > 0
            ? ["activity"]
            : []
        ),
      ]
    );

  if (
    userAskedMisakiWeather(
      message
    )
  ) {
    cleaned =
      removeProblemSentences(
        cleaned,
        (sentence) =>
          containsAny(
            sentence,
            [
              "そっちはどう",
              "そちらはどう",
              "そっちは今どんな感じ",
              "そっちの天気は",
              "傘持ったほう",
              "傘を持ったほう",
              "傘忘れないで",
              "濡れないようにして",
              "一日安定しそう",
              "大きく崩れなさそう",
              "荒れなさそう",
            ]
          )
            ? ["weather"]
            : []
      );
  }

  return cleaned || reply.trim();
}

/* =========================================================
   GEMINI
========================================================= */

function parseGeminiText(
  rawText: unknown
): GeminiResult | null {
  if (
    typeof rawText !== "string" ||
    !rawText.trim()
  ) {
    return null;
  }

  try {
    return JSON.parse(
      rawText
    ) as GeminiResult;
  } catch {
    return null;
  }
}

/* =========================================================
   POST
========================================================= */

export async function POST(
  request: Request
) {
  let operation: LegacyOperation | null = null;
  let operationHandled = false;
  const traceId =
    crypto.randomUUID()
      .slice(0, 8);
  const requestStartedAt =
    Date.now();

  async function measureStage<T>(
    stage: string,
    task: () => Promise<T>
  ): Promise<T> {
    const startedAt =
      Date.now();

    try {
      const result =
        await task();

      console.log(
        "CHAT STAGE:",
        {
          traceId,
          stage,
          elapsedMs:
            Date.now() -
            startedAt,
          ok: true,
        }
      );

      return result;
    } catch (error) {
      console.error(
        "CHAT STAGE:",
        {
          traceId,
          stage,
          elapsedMs:
            Date.now() -
            startedAt,
          ok: false,
          error:
            error instanceof Error
              ? error.message
              : String(error),
        }
      );

      throw error;
    }
  }

  let chargedRequestId:
    string | null = null;
  let chargedSupabase:
    SupabaseClient | null = null;

  async function refundIfCharged() {
    if (
      !chargedRequestId ||
      !chargedSupabase
    ) {
      return null;
    }

    if (operation) await progressOperation(operation, 'refund_pending');
    const refunded =
      await refundDailyMessage(
        chargedSupabase,
        chargedRequestId
      );

    if (operation) {
      operationHandled = await progressOperation(operation, refunded ? 'refunded' : 'unknown');
    }

    chargedRequestId = null;
    chargedSupabase = null;

    return refunded;
  }

  try {
    const {
      message,
      history,
      memory,
      currentTime,
      relationshipPoints,
      misakiTodayMemory,
    } =
      await measureStage(
        "request-json",
        () =>
          request.json()
      );

    if (
      !message ||
      typeof message !==
        "string"
    ) {
      return Response.json(
        {
          error:
            "メッセージを入力してね。",
        },
        {
          status: 400,
        }
      );
    }

    const apiKey =
      process.env
        .GEMINI_API_KEY;

    if (!apiKey) {
      return Response.json(
        {
          error:
            "今ちょっと調子が悪いみたい。少し待ってからもう一度話しかけてね。",
        },
        {
          status: 500,
        }
      );
    }

    const authorization =
      request.headers.get(
        "authorization"
      ) ?? "";

    if (
      !authorization.startsWith(
        "Bearer "
      )
    ) {
      return Response.json(
        {
          error:
            "ログイン情報を確認できませんでした。ページを再読み込みしてね。",
        },
        {
          status: 401,
        }
      );
    }

    const accessToken =
      authorization
        .slice(
          "Bearer ".length
        )
        .trim();

    let supabase =
      createAuthenticatedSupabase(
        accessToken
      );

    const {
      data: userData,
      error: userError,
    } =
      await measureStage(
        "auth-get-user",
        () =>
          supabase.auth.getUser(
            accessToken
          )
      );

    if (
      userError ||
      !userData.user
    ) {
      return Response.json(
        {
          error:
            "ログイン情報を確認できませんでした。ページを再読み込みしてね。",
        },
        {
          status: 401,
        }
      );
    }

    try {
      operation = await admitOperation('chat', userData.user.id);
      supabase = operationClient(accessToken, operation);
    } catch { return maintenanceResponse(); }
    const usageRequestId = operation.trackingKey;

    const {
      data: usageData,
      error: usageError,
    } =
      await measureStage(
        "usage-consume",
        () =>
          consumeDailyMessageWithRetry(
            supabase,
            usageRequestId
          )
      );

    if (usageError) {
      return Response.json(
        {
          error:
            "利用回数を確認できませんでした。少ししてからもう一度試してね。",
        },
        {
          status: 500,
        }
      );
    }

    const usage =
