    async function generateReply(
      retryProblems?: string[]
    ) {
      const retryGuide =
        retryProblems &&
        retryProblems.length > 0
          ? `

【前の返答は不採用】

問題：
${retryProblems
  .map(
    (problem) =>
      `・${problem}`
  )
  .join("\n")}

最初から作り直してください。

今日の美咲は
「${
  misakiDayType === "work"
    ? "仕事の日"
    : "休みの日"
}」です。

美咲自身の具体的な過去行動は、
会話履歴または今日の記憶に
根拠がある場合だけ使ってください。

ユーザーの職業・居住地・名前も、
会話または長期記憶に
根拠があるものだけ使ってください。

名前を知っていても
毎回名前を呼ばないでください。

天気について、
架空の情報入手経路や
確認できない時間経過を
作らないでください。

必ずJSONだけを返してください。
`
          : "";

      const controller =
        new AbortController();
      const startedAt =
        Date.now();
      const timeout =
        setTimeout(
          () =>
            controller.abort(),
          GEMINI_TIMEOUT_MS
        );

      const attempt =
        retryProblems &&
        retryProblems.length > 0
          ? "retry"
          : "initial";
      const hasSupplementaryUnicode =
        /[\uD800-\uDBFF][\uDC00-\uDFFF]/
          .test(
            message
          );

      console.log(
        "GEMINI FETCH START:",
        {
          traceId,
          attempt,
          messageLength:
            message.length,
          hasSupplementaryUnicode,
        }
      );

      try {
        const response =
          await fetch(
            `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent?key=${apiKey}`,
            {
              method: "POST",
              headers: {
                "Content-Type":
                  "application/json",
              },
              signal:
                controller.signal,
              body:
                JSON.stringify({
                  systemInstruction: {
                    parts: [
                      {
                        text:
                          baseSystemPrompt +
                          retryGuide,
                      },
                    ],
                  },
                  contents: [
                    ...contents,
                    {
                      role: "user",
                      parts: [
                        {
                          text: message,
                        },
                      ],
                    },
                  ],
                  generationConfig: {
                    responseMimeType:
                      "application/json",
                  },
                }),
            }
          );

        const elapsedMs =
          Date.now() -
          startedAt;

        console.log(
          "GEMINI FETCH END:",
          {
            traceId,
            attempt,
            status:
              response.status,
            elapsedMs,
          }
        );

        const data =
          await response.json();

        if (!response.ok) {
          console.error(
            "GEMINI API ERROR:",
            {
              traceId,
              attempt,
              status:
                response.status,
              elapsedMs,
              data,
            }
          );

          return null;
        }

        return parseGeminiText(
          data?.candidates?.[0]
            ?.content?.parts?.[0]
            ?.text
        );
      } catch (error) {
        const elapsedMs =
          Date.now() -
          startedAt;

        if (
          error instanceof
            Error &&
          error.name ===
            "AbortError"
        ) {
          console.error(
            "GEMINI FETCH TIMEOUT:",
            {
              traceId,
              attempt,
              elapsedMs,
              messageLength:
                message.length,
              hasSupplementaryUnicode,
            }
          );

          throw new Error(
            "GEMINI_TIMEOUT"
          );
        }

        console.error(
          "GEMINI FETCH FAILED:",
          {
            traceId,
            attempt,
            elapsedMs,
            error,
          }
        );

        throw error;
      } finally {
        clearTimeout(
          timeout
        );
      }
    }

    let parsed =
      await generateReply();

    if (!parsed) {
      const refunded =
        await refundIfCharged();

      return Response.json(
        {
          error:
            "美咲の返事をうまく読み取れなかったみたい。もう一度話しかけてね。",
          ...(refunded
            ? {
                usage: {
                  messageCount:
                    refunded.message_count ?? 0,
                  remaining:
                    refunded.remaining ?? 0,
                  isPremium:
                    refunded.is_premium === true,
                },
              }
            : {}),
        },
        {
          status: 500,
        }
      );
    }

    let reply =
      typeof parsed.reply ===
      "string"
        ? parsed.reply.trim()
        : "";

    if (!reply) {
      const refunded =
        await refundIfCharged();

      return Response.json(
        {
          error:
            "美咲から返事が来なかったみたい。もう一度話しかけてね。",
