            ? {
                usage: {
                  messageCount:
                    refunded.message_count ?? 0,
                  remaining:
                    refunded.remaining ?? 0,
                  isPremium:
                    refunded.is_premium === true,
                },
              }
            : {}),
        },
        {
          status: 500,
        }
      );
    }

    const firstProblems =
      getReplyProblems(
        reply,
        message,
        safeCurrentTime,
        safeHistory,
        activityEvidence,
        misakiDayType
      );

    if (
      firstProblems.length > 0
    ) {
