          Date.now() -
          requestStartedAt,
        error,
      }
    );

    const refunded =
      await refundIfCharged();

    console.log(
      "CHAT TOTAL:",
      {
        traceId,
        elapsedMs:
          Date.now() -
          requestStartedAt,
        ok: false,
      }
    );

    return Response.json(
      {
        error:
          "今ちょっと美咲とつながりにくいみたい。少ししてからもう一度話しかけてね。",
        ...(refunded
          ? {
              usage: {
                messageCount:
                  refunded.message_count ?? 0,
                remaining:
                  refunded.remaining ?? 0,
                isPremium:
                  refunded.is_premium === true,
              },
            }
          : {}),
      },
      {
        status: 500,
      }
    );
  } finally {
    if (operation && !operationHandled) {
      // Premium failures need no refund. A lost usage response or failed refund
      // cannot be cleared: the DB rejects failed until its usage evidence agrees.
      if (!await progressOperation(operation, 'failed')) await progressOperation(operation, 'unknown');
    }
  }
}

