"use client";
import { saveLegacyTurn } from '../../lib/legacy-browser-drain';

import {
  useEffect,
  useState,
} from "react";

import {
  supabase,
} from "../../lib/supabase";

import {
  registerPushSubscription,
  sendTestPushNotification,
} from "../../lib/push-notifications";

type ChatMessage = {
  role: "misaki" | "user";
  text: string;
};

type DailyUsage = {
  date: string;
  count: number;
};

type MisakiTodayMemory = {
  date: string;
  items: string[];
};

type Plan =
  | "free"
  | "premium";

type UsageRpcResult = {
  message_count?: number;
  remaining?: number;
  is_premium?: boolean;
};

type ApiUsage = {
  messageCount?: number;
  remaining?: number;
  isPremium?: boolean;
};

const STORAGE_KEY =
  "misaki-chat-history";

const MEMORY_KEY =
  "misaki-long-term-memory";

const RELATIONSHIP_KEY =
  "misaki-relationship-points";

const MISAKI_TODAY_MEMORY_KEY =
  "misaki-today-memory";

const MAX_MESSAGES = 60;

// 無料版は1日20往復まで
const FREE_DAILY_LIMIT = 20;

const INITIAL_MESSAGES:
  ChatMessage[] = [];



function getJapanDateKey() {
  return new Date()
    .toLocaleDateString(
      "ja-JP",
      {
        timeZone:
          "Asia/Tokyo",

        year:
          "numeric",

        month:
          "2-digit",

        day:
          "2-digit",
      }
    );
}

function getJapanCurrentTime() {
  return new Date()
    .toLocaleString(
      "ja-JP",
      {
        timeZone:
          "Asia/Tokyo",

        year:
          "numeric",

        month:
          "2-digit",

        day:
          "2-digit",

        weekday:
          "short",

        hour:
          "2-digit",

        minute:
          "2-digit",

        hour12:
          false,
      }
    );
}

function createEmptyTodayMemory():
  MisakiTodayMemory {
  return {
    date:
      getJapanDateKey(),

    items: [],
  };
}

function isPremiumActive(
  plan:
    | string
    | null
    | undefined,

  premiumUntil:
    | string
    | null
    | undefined
) {
  if (
    plan !==
    "premium"
  ) {
    return false;
  }

  if (
    !premiumUntil
  ) {
    return true;
  }

  const expiresAt =
    new Date(
      premiumUntil
    ).getTime();

  if (
    !Number.isFinite(
      expiresAt
    )
  ) {
    return false;
  }

  return (
    expiresAt >
    Date.now()
  );
}

function getFirstRpcRow<T>(
  value: unknown
): T | null {
  if (
    Array.isArray(
      value
    ) &&
    value.length >
      0
  ) {
    return value[0] as T;
  }

  if (
    value &&
    typeof value ===
      "object"
  ) {
    return value as T;
  }

  return null;
}

export default function ChatPage() {
  const [
    message,
    setMessage,
  ] =
    useState("");

  const [
    messages,
    setMessages,
  ] =
    useState<
      ChatMessage[]
    >(
      INITIAL_MESSAGES
    );

  const [
    memory,
    setMemory,
  ] =
    useState<
      string[]
    >([]);

  const [
    misakiTodayMemory,
    setMisakiTodayMemory,
  ] =
    useState<
      MisakiTodayMemory
    >(
      createEmptyTodayMemory()
    );

  const [
    relationshipPoints,
    setRelationshipPoints,
  ] =
    useState(0);

  const [
    dailyUsage,
    setDailyUsage,
  ] =
    useState<
      DailyUsage
    >({
      date:
        getJapanDateKey(),

      count:
        0,
    });

  const [
    plan,
    setPlan,
  ] =
    useState<
      Plan
    >(
      "free"
    );

  const [
    accountLoaded,
    setAccountLoaded,
  ] =
    useState(
      false
    );

  const [
    showPremium,
    setShowPremium,
  ] =
    useState(
      false
    );

  const [
    showMemory,
    setShowMemory,
  ] =
    useState(
      false
    );

  const [
    showMenu,
    setShowMenu,
  ] =
    useState(
      false
    );

  const [
    loading,
    setLoading,
  ] =
    useState(
      false
    );

  const [
    sendError,
    setSendError,
  ] =
    useState(
      ""
    );

  const [
    loaded,
    setLoaded,
  ] =
    useState(
      false
    );

  const [
    notificationPermission,
    setNotificationPermission,
  ] =
    useState<
      | "default"
      | "granted"
      | "denied"
      | "unsupported"
    >(
      "default"
    );

  const isPremium =
    plan ===
    "premium";

  const today =
    getJapanDateKey();

  const usageCountToday =
    dailyUsage.date ===
    today
      ? dailyUsage.count
      : 0;

  const freeRemaining =
    Math.max(
      0,
      FREE_DAILY_LIMIT -
        usageCountToday
    );

  const freeLimitReached =
    accountLoaded &&
    !isPremium &&
    usageCountToday >=
      FREE_DAILY_LIMIT;

  useEffect(
    () => {
      let active =
        true;

      async function loadEntitlement(
        userId:
          string
      ) {
        for (
          let attempt =
            0;
          attempt <
            5;
          attempt +=
            1
        ) {
          const {
            data,
            error,
          } =
            await supabase
              .from(
                "user_entitlements"
              )
              .select(
                "plan,premium_until"
              )
              .eq(
                "user_id",
                userId
              )
              .maybeSingle();

          if (
            error
          ) {
            throw error;
          }

          if (
            data
          ) {
            return isPremiumActive(
              data.plan,
              data.premium_until
            );
          }

          await new Promise(
            (
              resolve
            ) =>
              window.setTimeout(
                resolve,
                350
              )
          );
        }

        return false;
      }

      async function loadDailyUsage() {
        const {
          data,
          error,
        } =
          await supabase.rpc(
            "get_daily_message_usage"
          );

        if (
          error
        ) {
          throw error;
        }

        const usage =
          getFirstRpcRow<
            UsageRpcResult
          >(
            data
          );

        return {
          count:
            typeof usage
              ?.message_count ===
              "number"
              ? Math.max(
                  0,
                  Math.floor(
                    usage
                      .message_count
                  )
                )
              : 0,

          isPremium:
            usage
              ?.is_premium ===
            true,
        };
      }

      async function initializeAccount() {
        try {
          const {
            data:
              sessionData,
            error:
              sessionError,
          } =
            await supabase
              .auth
              .getSession();

          if (
            sessionError
          ) {
            throw sessionError;
          }

          let user =
            sessionData
              .session
              ?.user ??
            null;

          if (
            !user
          ) {
            const {
              data:
                signInData,
              error:
                signInError,
            } =
              await supabase
                .auth
                .signInAnonymously();

            if (
              signInError
            ) {
              throw signInError;
            }

            user =
              signInData
                .user ??
              null;
          }

          if (
            !user
          ) {
            throw new Error(
              "Supabase user was not created."
            );
          }

          const [
            entitlementPremium,
            usage,
          ] =
            await Promise
              .all([
                loadEntitlement(
                  user.id
                ),

                loadDailyUsage(),
              ]);

          if (
            !active
          ) {
            return;
          }

          const premium =
            entitlementPremium ||
            usage
              .isPremium;

          setPlan(
            premium
              ? "premium"
              : "free"
          );

          setDailyUsage({
            date:
              getJapanDateKey(),

            count:
              usage.count,
          });
        } catch (
          error
        ) {
          console.error(
            "Supabase account initialization failed:",
            error
          );

          if (
            active
          ) {
            setPlan(
              "free"
            );

            setDailyUsage({
              date:
                getJapanDateKey(),

              count:
                0,
            });
          }
        } finally {
          if (
            active
          ) {
            setAccountLoaded(
              true
            );
          }
        }
      }

      initializeAccount();

      return () => {
        active =
          false;
      };
    },
    []
  );

  useEffect(
    () => {
      if (
        !accountLoaded
      ) {
        return;
      }

      if (
        isPremium
      ) {
        setShowPremium(
          false
        );

        return;
      }

      if (
        usageCountToday >=
        FREE_DAILY_LIMIT
      ) {
        setShowPremium(
          true
        );
      }
    },
    [
      accountLoaded,
      isPremium,
      usageCountToday,
    ]
  );

  useEffect(
    () => {
      if (
        "serviceWorker" in
        navigator
      ) {
        navigator
          .serviceWorker
          .register(
            "/sw.js"
          )
          .then(
            (
              registration
            ) => {
              console.log(
                "Service Worker registered:",
                registration
              );
            }
          )
          .catch(
            (
              error
            ) => {
              console.error(
                "Service Worker registration failed:",
                error
              );
            }
          );
      }
    },
    []
  );

  useEffect(
    () => {
      if (
        !(
          "Notification" in
          window
        )
      ) {
        setNotificationPermission(
          "unsupported"
        );

        return;
      }

      setNotificationPermission(
        Notification
          .permission
      );
    },
    []
  );

  useEffect(
    () => {
      try {
        const savedMessages =
          localStorage
            .getItem(
              STORAGE_KEY
            );

        const savedMemory =
          localStorage
            .getItem(
              MEMORY_KEY
            );

        const savedRelationship =
          localStorage
            .getItem(
              RELATIONSHIP_KEY
            );

        const savedTodayMemory =
          localStorage
            .getItem(
              MISAKI_TODAY_MEMORY_KEY
            );

        let parsedMessages:
          | ChatMessage[]
          | null =
          null;

        if (
          savedMessages
        ) {
          const parsed =
            JSON.parse(
              savedMessages
            );

          if (
            Array.isArray(
              parsed
            )
          ) {
            parsedMessages =
              parsed
                .filter(
                  (
                    item
                  ) =>
                    item &&
                    (
                      item
                        .role ===
                        "user" ||
                      item
                        .role ===
                        "misaki"
                    ) &&
                    typeof item
                      .text ===
                      "string"
                )
                .slice(
                  -MAX_MESSAGES
                );

            setMessages(
              parsedMessages
            );
          }
        }

        if (
          savedMemory
        ) {
          const parsedMemory =
            JSON.parse(
              savedMemory
            );

          if (
            Array.isArray(
              parsedMemory
            )
          ) {
            setMemory(
              parsedMemory
                .filter(
                  (
                    item
                  ) =>
                    typeof item ===
                    "string"
                )
            );
          }
        }

        if (
          savedRelationship
        ) {
          const parsedPoints =
            Number(
              savedRelationship
            );

          if (
            Number
              .isFinite(
                parsedPoints
              ) &&
            parsedPoints >=
              0
          ) {
            setRelationshipPoints(
              Math.floor(
                parsedPoints
              )
            );
          }
        } else if (
          parsedMessages
        ) {
          const previousUserMessages =
            parsedMessages
              .filter(
                (
                  item
                ) =>
                  item.role ===
                  "user"
              )
              .length;

          setRelationshipPoints(
            previousUserMessages
          );
        }

        const currentDate =
          getJapanDateKey();

        if (
          savedTodayMemory
        ) {
          const parsedTodayMemory =
            JSON.parse(
              savedTodayMemory
            );

          if (
            parsedTodayMemory &&
            parsedTodayMemory
              .date ===
              currentDate &&
            Array.isArray(
              parsedTodayMemory
                .items
            )
          ) {
            setMisakiTodayMemory({
              date:
                currentDate,

              items:
                parsedTodayMemory
                  .items
                  .filter(
                    (
                      item:
                        unknown
                    ) =>
                      typeof item ===
                        "string" &&
                      item
                        .trim()
                        .length >
                        0
                  )
                  .map(
                    (
                      item:
                        string
                    ) =>
                      item
                        .trim()
                  )
                  .slice(
                    -12
                  ),
            });
          } else {
            setMisakiTodayMemory({
              date:
                currentDate,

              items:
                [],
            });
          }
        } else {
          setMisakiTodayMemory({
            date:
              currentDate,

            items:
              [],
          });
        }
      } catch (
        error
      ) {
        console.error(
          "Failed to load saved data:",
          error
        );

        const currentDate =
          getJapanDateKey();

        setMisakiTodayMemory({
          date:
            currentDate,

          items:
            [],
        });
      } finally {
        setLoaded(
          true
        );
      }
    },
    []
  );

  useEffect(
    () => {
      if (
        !loaded
      ) {
        return;
      }

      try {
        const limitedMessages =
          messages
            .slice(
              -MAX_MESSAGES
            );

        localStorage
          .setItem(
            STORAGE_KEY,

            JSON.stringify(
              limitedMessages
            )
          );
      } catch (
        error
      ) {
        console.error(
          "Failed to save chat history:",
          error
        );
      }
    },
    [
      messages,
      loaded,
    ]
  );

  useEffect(
    () => {
      if (
        !loaded
      ) {
        return;
      }

      try {
        localStorage
          .setItem(
            MEMORY_KEY,

            JSON.stringify(
              memory
            )
          );
      } catch (
        error
      ) {
        console.error(
          "Failed to save memory:",
          error
        );
      }
    },
    [
      memory,
      loaded,
    ]
  );

  useEffect(
    () => {
      if (
        !loaded
      ) {
        return;
      }

      try {
        const currentDate =
          getJapanDateKey();

        const safeTodayMemory =
          misakiTodayMemory
            .date ===
            currentDate
            ? misakiTodayMemory
            : {
                date:
                  currentDate,

                items:
                  [],
              };

        localStorage
          .setItem(
            MISAKI_TODAY_MEMORY_KEY,

            JSON.stringify(
              safeTodayMemory
            )
          );

        if (
          misakiTodayMemory
            .date !==
          currentDate
        ) {
          setMisakiTodayMemory(
            safeTodayMemory
          );
        }
      } catch (
        error
      ) {
        console.error(
          "Failed to save Misaki today memory:",
          error
        );
      }
    },
    [
      misakiTodayMemory,
      loaded,
    ]
  );

  useEffect(
    () => {
      if (
        !loaded
      ) {
        return;
      }

      try {
        localStorage
          .setItem(
            RELATIONSHIP_KEY,

            String(
              relationshipPoints
            )
          );
      } catch (
        error
      ) {
        console.error(
          "Failed to save relationship points:",
          error
        );
      }
    },
    [
      relationshipPoints,
      loaded,
    ]
  );

  async function getAccessToken() {
    const {
      data,
      error,
    } =
      await supabase
        .auth
        .getSession();

    if (
      error
    ) {
      throw error;
    }

    const accessToken =
      data
        .session
        ?.access_token;

    if (
      !accessToken
    ) {
      throw new Error(
        "ログイン情報を確認できませんでした。ページを再読み込みしてね。"
      );
    }

    return accessToken;
  }

  function applyApiUsage(
    value:
      unknown
  ) {
    if (
      !value ||
      typeof value !==
        "object"
    ) {
      return;
    }

    const usage =
      value as
        ApiUsage;

    if (
      usage
        .isPremium ===
      true
    ) {
      setPlan(
        "premium"
      );
    }

    if (
      typeof usage
        .messageCount ===
        "number" &&
      Number.isFinite(
        usage
          .messageCount
      )
    ) {
      setDailyUsage({
        date:
          getJapanDateKey(),

        count:
          Math.max(
            0,

            Math.floor(
              usage
                .messageCount
            )
          ),
      });
    }
  }

  async function requestNotificationPermission() {
    if (
      !(
        "Notification" in
        window
      )
    ) {
      alert(
        "この環境では通知機能を利用できません。"
      );

      setNotificationPermission(
        "unsupported"
      );

      return;
    }

    if (
      !(
        "serviceWorker" in
        navigator
      )
    ) {
      alert(
        "この環境では通知機能を利用できません。"
      );

      setNotificationPermission(
        "unsupported"
      );

      return;
    }

    if (
      !(
        "PushManager" in
        window
      )
    ) {
      alert(
        "このブラウザはPush通知に対応していません。"
      );

      setNotificationPermission(
        "unsupported"
      );

      return;
    }

    try {
      await navigator
        .serviceWorker
        .ready;

      const permission =
        await Notification
          .requestPermission();

      setNotificationPermission(
        permission
      );

      if (
        permission ===
        "denied"
      ) {
        alert(
          "通知が許可されませんでした。端末の設定から美咲の通知を許可してください。"
        );

        return;
      }

      if (
        permission !==
        "granted"
      ) {
        return;
      }

      await registerPushSubscription();

      const accessToken =
        await getAccessToken();

      try {
        await sendTestPushNotification(
          accessToken
        );

        alert(
          "通知をONにしました。今、美咲からテスト通知を送ったよ。"
        );
      } catch (
        testError
      ) {
        console.error(
          "Test push notification failed:",
          testError
        );

        alert(
          "通知端末の登録はできました。テスト通知だけ送信できませんでした。"
        );
      }
    } catch (
      error
    ) {
      console.error(
        "Push notification setup error:",
        error
      );

      const errorMessage =
        error instanceof
        Error
          ? error.message
          : "通知の設定に失敗しました。";

      alert(
        errorMessage
      );
    }
  }

  function resetChat() {
    const confirmed =
      window
        .confirm(
          "美咲との会話履歴をリセットしますか？"
        );

    if (
      !confirmed
    ) {
      return;
    }

    localStorage
      .removeItem(
        STORAGE_KEY
      );

    setMessages(
      []
    );

    setMessage(
      ""
    );

    setShowMenu(
      false
    );
  }

  function deleteMemory(
    index:
      number
  ) {
    const confirmed =
      window
        .confirm(
          "この記憶を削除しますか？"
        );

    if (
      !confirmed
    ) {
      return;
    }

    setMemory(
      (
        prev
      ) =>
        prev
          .filter(
            (
              _,
              i
            ) =>
              i !==
              index
          )
    );
  }

  function resetMemory() {
    if (
      memory.length ===
      0
    ) {
      return;
    }

    const confirmed =
      window
        .confirm(
          "美咲の長期記憶をすべて削除しますか？\n会話履歴は残ります。"
        );

    if (
      !confirmed
    ) {
      return;
    }

    localStorage
      .removeItem(
        MEMORY_KEY
      );

    setMemory(
      []
    );
  }

  function openPremium() {
    if (
      isPremium
    ) {
      return;
    }

    setShowPremium(
      true
    );
  }

  function startPremium() {
    alert(
      "プレミアム決済は次の工程で接続します。今はまだ料金は発生しません。"
    );
  }

  function applyTodayMemory(
    value:
      unknown
  ) {
    if (
      !value ||
      typeof value !==
        "object"
    ) {
      return;
    }

    const data =
      value as {
        date?:
          unknown;

        items?:
          unknown;
      };

    const currentDate =
      getJapanDateKey();

    if (
      data.date !==
        currentDate ||
      !Array.isArray(
        data.items
      )
    ) {
      return;
    }

    const items =
      data
        .items
        .filter(
          (
            item:
              unknown
          ) =>
            typeof item ===
              "string" &&
            item
              .trim()
              .length >
              0
        )
        .map(
          (
            item
          ) =>
            (
              item as string
            )
              .trim()
        )
        .slice(
          -12
        );

    setMisakiTodayMemory({
      date:
        currentDate,

      items:
        Array.from(
          new Set(
            items
          )
        ),
    });
  }

  async function sendMessage() {
    const text =
      message
        .trim();

    if (
      !text ||
      loading ||
      !accountLoaded
    ) {
      return;
    }

    const currentDate =
      getJapanDateKey();

    if (
      !isPremium &&
      usageCountToday >=
        FREE_DAILY_LIMIT
    ) {
      setShowPremium(
        true
      );

      return;
    }

    setLoading(
      true
    );

    setSendError(
      ""
    );

    try {
      const accessToken =
        await getAccessToken();
      const sendOwner = (await supabase.auth.getSession()).data.session?.user.id;
      if (!sendOwner) throw new Error('Authentication required');

      const userMessage:
        ChatMessage = {
          role:
            "user",

          text,
        };

      const newMessages =
        [
          ...messages,
          userMessage,
        ]
          .slice(
            -MAX_MESSAGES
          );

      setMessages(
        newMessages
      );

      setMessage(
        ""
      );

      const nextRelationshipPoints =
        relationshipPoints +
        1;

      const currentTime =
        getJapanCurrentTime();

      const todayMemoryForRequest =
        misakiTodayMemory
          .date ===
          currentDate
          ? misakiTodayMemory
          : {
              date:
                currentDate,

              items:
                [],
            };

      const res =
        await fetch(
          "/api/chat",
          {
            method:
              "POST",

            headers: {
              "Content-Type":
                "application/json",

              Authorization:
                `Bearer ${accessToken}`,
            },

            body:
              JSON.stringify({
                message:
                  text,

                history:
                  messages
                    .slice(
                      -MAX_MESSAGES
                    ),

                memory,

                misakiTodayMemory:
                  todayMemoryForRequest,

                currentTime,

                relationshipPoints:
                  nextRelationshipPoints,
              }),
          }
        );

      const data =
        await res
          .json();
      if ((await supabase.auth.getSession()).data.session?.user.id !== sendOwner) return;

      applyApiUsage(
        data?.usage
      );

      if (data?.maintenance === true) {
        setMessages(messages);
        setMessage(text);
        setSendError(data.error);
        return;
      }

      if (
        res.status ===
        429
      ) {
        setShowPremium(
          true
        );

        setMessages(
          (
            prev
          ) =>
            prev
              .filter(
                (
                  item,
                  index
                ) =>
                  !(
                    index ===
                      prev.length -
                        1 &&
                    item.role ===
                      "user" &&
                    item.text ===
                      text
                  )
              )
        );

        return;
      }

      if (
        !res.ok
      ) {
        throw new Error(
          data?.error ||
            "通信に失敗しました"
        );
      }

      if (
        Array.isArray(
          data.memory
        )
      ) {
        setMemory(
          data.memory
            .filter(
              (
                item:
                  unknown
              ) =>
                typeof item ===
                "string"
            )
        );
      }

      applyTodayMemory(
        data
          .misakiTodayMemory
      );

      setRelationshipPoints(
        nextRelationshipPoints
      );

      setMessages(
        (
          prev
        ) =>
          [
            ...prev,

            {
              role:
                "misaki" as const,

              text:
                data.reply ||
                "返事を取得できませんでした。",
            },
          ]
            .slice(
              -MAX_MESSAGES
            )
      );
      if (data.maintenanceOperation) {
        await saveLegacyTurn(data.maintenanceOperation,
          [...newMessages, { role: 'misaki', text: data.reply }],
          Array.isArray(data.memory) ? data.memory : memory,
          data.misakiTodayMemory ?? todayMemoryForRequest, nextRelationshipPoints, sendOwner);
      }
    } catch (
      error:
        any
    ) {
      console.error(
        "Chat message error:",
        error
      );

      setSendError(
        error instanceof Error &&
        error.message
          ? error.message
          : "返事を受け取れませんでした。もう一度送ってみてね。"
      );
    } finally {
      setLoading(
        false
      );
    }
  }

